from pathlib import Path
root=Path(__file__).parent
nav=[('Home','index.html'),('Experience','experience.html'),('Projects','projects.html'),('Skills','skills.html'),('About','about.html'),('Journey','journey.html'),('Resume','resume.html'),('Contact','contact.html')]
def page(title, body, active=''):
    links=''.join(f'<a {"aria-current=page" if label==active else ""} href="{href}">{label}</a>' for label,href in nav)
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Mohammad Mansouri — Civil Engineer specializing in structural design, site supervision and construction quality control."><title>{title} | Mohammad Mansouri</title><link rel="stylesheet" href="assets/styles.css"><script defer src="assets/site.js"></script></head><body><header><div class="container nav"><a class="brand" href="index.html">Mohammad Mansouri</a><button class="menu-toggle" aria-expanded="false">Menu</button><nav aria-label="Main navigation">{links}</nav></div></header><main>{body}</main><footer><div class="container footer-row"><span>© 2026 Mohammad Mansouri</span><span><a href="mailto:s.mohammad.mansouri67@gmail.com">Email</a> · <a href="https://www.linkedin.com/in/mohammad-mansouri-68a03225a/" target="_blank" rel="noopener noreferrer">LinkedIn</a></span></div></footer></body></html>'''
def head(title): return f'<section class="page-head"><div class="container"><div class="eyebrow">Mohammad Mansouri</div><h1>{title}</h1></div></section>'
pages={}
pages['index.html']=page('Civil Engineer', '''<section class="hero"><div class="container hero-grid"><div><div class="eyebrow">Civil Engineering</div><h1>Mohammad Mansouri</h1><div class="hero-title">Civil Engineer | Structural Design | Site Supervision | Construction Quality Control</div><p class="lead">I am a Civil Engineer with experience in structural analysis and design, construction site supervision, and quality control across building, industrial, and mining-related projects.</p><p class="lead">My professional background combines the design of reinforced-concrete and steel structures with hands-on experience in construction execution, concrete works, reinforcement inspection, material testing, and technical coordination. I aim to bring together sound engineering principles, practical construction knowledge, and attention to quality and technical requirements throughout a project.</p><div class="actions"><a class="button" href="projects.html">View Projects</a><a class="button secondary" href="resume.html">View Resume</a></div></div><div class="photo-placeholder"><div><strong>Professional photograph</strong><small>Reserved space — photo to be added later.</small></div></div></div></section><section class="section"><div class="container"><h2>Experience across design and construction</h2><p class="section-intro">My work combines structural engineering calculations with practical site experience and construction quality control.</p><div class="cards"><article class="card"><h3>Structural Design</h3><p>Structural analysis and design for reinforced-concrete and steel buildings, including modelling, engineering calculations, and technical drawings.</p><a href="projects.html">Explore design work →</a></article><article class="card"><h3>Site Supervision & Quality Control</h3><p>Civil and structural supervision on industrial and mining-related projects, including concrete works, steel structures, inspection, testing, and coordination.</p><a href="experience.html">View experience →</a></article></div></div></section><section class="section alt"><div class="container"><h2>Featured project</h2><h3>Daralu Copper Mine — Civil and Structural Supervision</h3><p>Worked as a Civil and Structural Supervisor, overseeing all steel structures and selected concrete buildings across the site, including the primary crusher building.</p><a href="projects.html">Project details →</a></div></section><section class="section"><div class="container"><h2>Technical focus</h2><ul class="pill-list"><li>Structural Analysis & Design</li><li>Reinforced Concrete</li><li>Steel Structures</li><li>Construction Supervision</li><li>Quality Control</li><li>ETABS</li><li>SAFE</li><li>SAP2000</li><li>AutoCAD</li></ul><a href="skills.html">View all technical skills →</a></div></section><section class="section alt"><div class="container"><h2>Professional inquiries</h2><p class="section-intro">Open to professional opportunities and collaboration in structural design, civil and structural supervision, and construction quality control.</p><a class="button" href="contact.html">Contact me</a></div></section>''','Home')
pages['experience.html']=page('Professional Experience',head('Professional Experience')+'''<section class="section"><div class="container prose"><div class="entry"><h2>Kian Madan Pars</h2><p class="meta">Civil Engineer | Site Supervision & Construction Quality Control · Jan 2018 – Jun 2026</p><p>Worked on industrial construction projects associated with a copper-mining complex in mountainous Kerman Province, Iran. Responsibilities included concrete production and placement, slump testing, cold-joint risk management, mass-concrete temperature monitoring, reinforcement inspection, material testing, earthworks, compaction, road construction, and coordination with contractors and site teams to resolve technical discrepancies.</p><p>The work included supervision related to a primary crusher building project involving approximately 12,000 m³ of concrete.</p></div><div class="entry"><h2>ATIE-NEGAR-KALUT-KAVIR</h2><p class="meta">Civil Engineer | Structural Design & Site Supervision · Dec 2012 – Mar 2018</p><p>Worked on reinforced-concrete and steel building projects of up to seven storeys. Responsibilities included structural modelling, engineering calculations, preparation of structural drawings, application of Iranian building regulations and seismic design requirements, and site supervision.</p><p>Software used included ETABS, SAFE, and SAP2000.</p></div><div class="entry"><h2>Freelance Structural Engineer</h2><p class="meta">Structural Design</p><p>Continued working on building design projects, preparing structural calculations and drawings alongside other professional responsibilities.</p></div></div></section>''','Experience')
pages['projects.html']=page('Projects',head('Projects')+'''<section class="section"><div class="container prose"><div class="entry"><h2>Daralu Copper Mine — Civil and Structural Supervision</h2><p class="meta">Civil & Structural Supervision | Steel Structures | Reinforced Concrete Construction | Quality Control</p><p>Worked as a Civil and Structural Supervisor at Daralu Copper Mine in Kerman Province, Iran, overseeing civil and structural construction activities across the site.</p><p>My responsibilities covered all steel structures and selected concrete buildings, including the primary crusher building. The work involved supervising construction activities, inspecting reinforcement and structural works, monitoring concrete production and placement, checking concrete slump, addressing cold-joint risks, monitoring mass-concrete temperatures, coordinating material testing, and working with contractors and site teams to resolve technical issues.</p></div><div class="entry"><h2>Reinforced-Concrete and Steel Building Design</h2><p class="meta">Structural Analysis | Structural Design | Engineering Calculations | Technical Drawings</p><p>Performed structural analysis and design for reinforced-concrete and steel buildings of up to seven storeys. The work included structural modelling, engineering calculations, preparation of structural drawings, and application of relevant Iranian building regulations and seismic design requirements.</p><p>Software used included ETABS, SAFE, and SAP2000.</p></div></div></section>''','Projects')
pages['skills.html']=page('Technical Skills',head('Technical Skills')+'''<section class="section"><div class="container cards"><article class="card"><h3>Structural Analysis and Design</h3><ul><li>Structural analysis and design of reinforced-concrete and steel buildings</li><li>Structural modelling and engineering calculations</li><li>Structural drawing preparation</li><li>Seismic design and code compliance</li></ul></article><article class="card"><h3>Construction Supervision</h3><ul><li>Civil and structural construction supervision</li><li>Steel structure inspection and construction monitoring</li><li>Reinforced-concrete construction supervision</li><li>Reinforcement inspection and drawing compliance</li><li>Earthworks, compaction, and road construction</li><li>Contractor coordination and resolution of technical discrepancies</li></ul></article><article class="card"><h3>Concrete Technology and Quality Control</h3><ul><li>Concrete production and placement</li><li>Concrete slump testing</li><li>Cold-joint prevention and control</li><li>Mass-concrete temperature monitoring</li><li>Reinforcement inspection and material testing</li><li>Construction quality assurance and quality control (QA/QC)</li></ul></article><article class="card"><h3>Engineering Software</h3><ul><li>ETABS</li><li>SAFE</li><li>SAP2000</li><li>AutoCAD</li><li>Microsoft Excel</li></ul></article><article class="card"><h3>Codes and Standards</h3><ul><li>Iranian National Building Regulations</li><li>Iranian Standard 2800 — Seismic Design Code</li><li>ASCE 7 — Minimum Design Loads and Associated Criteria for Buildings and Other Structures</li><li>ACI 318 — Building Code Requirements for Structural Concrete</li><li>AISC 360 — Specification for Structural Steel Buildings</li><li>AISC 341 — Seismic Provisions for Structural Steel Buildings</li><li>AISC 303 — Code of Standard Practice for Steel Buildings and Bridges</li></ul></article><article class="card"><h3>AI-Assisted Engineering Problem-Solving</h3><p>Efficient use of AI tools to investigate engineering questions, support technical analysis, interpret engineering references, and improve problem-solving workflows, with engineering judgment and verification against applicable codes and standards.</p></article></div></section>''','Skills')
pages['about.html']=page('About Me',head('About Me')+'''<section class="section"><div class="container prose"><p>I am a Civil Engineer with experience in structural design, freelance engineering, civil and structural supervision, and construction quality control across building and industrial projects.</p><p>Having worked in both design and construction environments, I understand the importance of connecting engineering calculations and drawings with the practical realities of construction. My experience includes reinforced-concrete and steel structures, structural analysis, engineering calculations, and supervising construction activities on large-scale industrial projects.</p><p>I value accurate calculations, practical solutions, clear technical documentation, and attention to construction quality. I believe that effective engineering requires both a sound understanding of technical principles and the ability to apply them under real project conditions.</p><p>I am also interested in using AI tools to investigate engineering questions, interpret technical references, and improve problem-solving workflows. I see AI as a tool to support engineering work, while engineering judgment, independent verification, and compliance with applicable codes and standards remain essential.</p></div></section>''','About')
pages['journey.html']=page('Professional Journey',head('Professional Journey')+'''<section class="section"><div class="container prose"><p>As a young man, I was interested in construction and problem-solving, which led me to pursue a degree in Civil Engineering at Shahid Bahonar University of Kerman. I later continued my education with a master's degree in Civil Engineering, specializing in Hydraulic Structures. After completing my studies, I began my professional career at ATIE-NEGAR-KALUT-KAVIR, where I gained my first professional experience in structural design.</p><h2>Structural Design and Freelance Work</h2><p>At ATIE-NEGAR-KALUT-KAVIR, I worked on reinforced-concrete and steel building projects, carrying out structural modelling, engineering calculations, and structural drawing preparation using ETABS, SAFE, and SAP2000.</p><p>After leaving the company, I continued working as a freelance structural engineer, undertaking building design projects and preparing structural calculations and drawings. This allowed me to continue developing my experience in building design alongside other professional responsibilities.</p><h2>My First Large-Scale Industrial Project</h2><p>My first experience with large-scale industrial construction came at Daralu Copper Mine in Kerman Province. I joined Kian Madan Pars as a Civil and Structural Supervisor, taking responsibility for supervising all steel structures and selected concrete buildings across the site, including the primary crusher.</p><p>My work involved supervising construction activities, monitoring concrete production and placement, checking concrete slump, addressing cold-joint risks, monitoring mass-concrete temperatures, inspecting reinforcement, coordinating material testing, and working with contractors and site teams to resolve technical issues. This experience gave me practical insight into the challenges of delivering large industrial structures while maintaining construction quality and meeting technical requirements.</p><h2>Engineering and AI-Assisted Problem-Solving</h2><p>Alongside my experience in structural design and construction supervision, I have developed an interest in using AI tools to solve practical engineering problems. I use these tools to investigate technical questions, interpret engineering references, and explore more efficient ways to approach engineering tasks.</p><p>My aim is to combine practical engineering experience with technology while maintaining sound engineering judgment and verifying technical conclusions against applicable codes and standards.</p></div></section>''','Journey')
pages['resume.html']=page('Resume',head('Resume')+'''<section class="section"><div class="container prose"><p class="lead">A concise overview of my engineering background, experience, and core expertise.</p><div class="actions"><a class="button" href="assets/Mohammad_Mansouri_CV.pdf" download>Download CV (PDF)</a></div><h2>Professional Summary</h2><p>Civil Engineer with experience in structural design, freelance engineering, civil and structural supervision, and construction quality control across building and industrial projects. Experienced in reinforced-concrete and steel structures, structural analysis, engineering calculations, and construction-site activities.</p><h2>Education</h2><ul><li>M.Sc. in Civil Engineering — Hydraulic Structures, Shahid Bahonar University of Kerman, Iran</li><li>B.Sc. in Civil Engineering, Shahid Bahonar University of Kerman, Iran</li></ul><h2>Professional Experience</h2><ul><li><strong>Kian Madan Pars:</strong> Civil and Structural Supervisor, with experience in industrial construction and construction quality control.</li><li><strong>ATIE-NEGAR-KALUT-KAVIR:</strong> Structural design and site supervision for building projects.</li><li><strong>Freelance Structural Engineer:</strong> Structural analysis, calculations, and drawings for building projects.</li></ul><h2>Core Expertise</h2><p>Structural analysis and design, reinforced-concrete and steel structures, civil and structural supervision, construction quality control, engineering calculations, technical drawings, and AI-assisted engineering problem-solving.</p><h2>Software</h2><p>ETABS, SAFE, SAP2000, AutoCAD, and Microsoft Excel.</p></div></section>''','Resume')
pages['contact.html']=page('Contact',head('Contact')+'''<section class="section"><div class="container prose"><div class="contact-panel"><p>I am open to professional opportunities and collaboration in structural design, civil and structural supervision, and construction quality control.</p><p>For professional inquiries, project opportunities, or potential collaboration, please feel free to get in touch.</p><p><strong>Email:</strong> <a href="mailto:s.mohammad.mansouri67@gmail.com">s.mohammad.mansouri67@gmail.com</a></p><p><strong>LinkedIn:</strong> <a href="https://www.linkedin.com/in/mohammad-mansouri-68a03225a/" target="_blank" rel="noopener noreferrer">linkedin.com/in/mohammad-mansouri-68a03225a/</a></p></div></div></section>''','Contact')
for name,html in pages.items(): (root/name).write_text(html,encoding='utf-8')
